import type { FlatToken, Theme, TokenGroup } from '../data/token.ts';
import { cssVariableName } from './css-variable-name.ts';
import { flattenTokens } from './flatten-tokens.ts';
import { formatCssValue } from './format-css-value.ts';

const HEADER =
  '/* Generated by `bun run build` from tokens/. Do not edit by hand: change the tokens and build. */';

function declaration({ path, type, value }: FlatToken, indent: string): string {
  return `${indent}${cssVariableName(path)}: ${formatCssValue(type, value)};`;
}

function rule(selectors: readonly string[], tokens: readonly FlatToken[], indent: string): string {
  const body = tokens.map((token) => declaration(token, `${indent}  `)).join('\n');
  return `${indent}${selectors.join(`,\n${indent}`)} {\n${body}\n${indent}}`;
}

/** Whether a value points at another token, which may be a theme's and change under a subtree. */
function refersToAnother(value: unknown): boolean {
  return JSON.stringify(value).includes('"{');
}

function selectorsFor({ name, mode }: Theme, isDefault: boolean): string[] {
  const own =
    mode === 'light' ? `[data-theme="${name}"]` : `[data-theme="${name}"][data-mode="dark"]`;
  if (!isDefault) return [own];
  return mode === 'light' ? [':root', own] : [':root:not([data-theme])[data-mode="dark"]', own];
}

function systemNight(theme: Theme): string {
  const selectors = [
    ':root:not([data-theme]):not([data-mode])',
    `[data-theme="${theme.name}"]:not([data-mode])`,
  ];
  const night = rule(selectors, flattenTokens(theme.tokens), '    ');
  return `  @media (prefers-color-scheme: dark) {\n${night}\n  }`;
}

/**
 * The CSS of the tokens, inside the `feitio.tokens` layer: base tokens on `:root` (those built on
 * a theme's tokens on every themed element too), then each theme by its `data-theme` and
 * `data-mode`. The default theme also answers on a page that sets neither, and its night version
 * follows the system when the page does not choose a mode.
 */
export function renderCss(
  base: TokenGroup,
  themes: readonly Theme[],
  defaultTheme: string,
): string {
  const tokens = flattenTokens(base);
  const plain = tokens.filter((token) => !refersToAnother(token.value));
  const linked = tokens.filter((token) => refersToAnother(token.value));
  const blocks = [rule([':root'], plain, '  ')];
  // A custom property resolves its var() where it is declared: tokens built on a theme's tokens
  // are declared again on every element that sets a theme, so a themed subtree gets its own.
  if (linked.length > 0) blocks.push(rule([':root', '[data-theme]', '[data-mode]'], linked, '  '));
  for (const theme of themes) {
    const isDefault = theme.name === defaultTheme;
    blocks.push(rule(selectorsFor(theme, isDefault), flattenTokens(theme.tokens), '  '));
    if (isDefault && theme.mode === 'dark') blocks.push(systemNight(theme));
  }
  return `${HEADER}\n@layer feitio.tokens {\n${blocks.join('\n\n')}\n}\n`;
}
